// Static game data: planets, system tiles, units, technologies, factions,
// objectives and map layouts (base game + Prophecy of Kings).
// The tables live in gen/gamedata.inc (generated by tools/gen_data.py).
#pragma once
#include <cstdint>
#include <string>

namespace ti {

enum class Trait : uint8_t { None, Cultural, Hazardous, Industrial };
enum class TechColor : int8_t { None = -1, Blue = 0, Green = 1, Red = 2, Yellow = 3 };
enum class Back : uint8_t { Blue, Red, Home, Special, Hyperlane };
// Uncharted: the Uncharted Space module (0.33.0); ThundersEdge: the Thunder's Edge module (0.34.0)
constexpr int kDsLevel = 6;  // Discordant Stars faction batches in this version (0.37.0: 1, 0.38.0: 2, 0.39.0: 3, 0.40.0: 4, 0.41.0: 5, 0.42.0: 6)
enum class Source : uint8_t { Base, PoK, Uncharted, ThundersEdge, Discordant };
enum class ObjPhase : uint8_t { Status, Action, Agenda };

enum class UnitType : uint8_t {
    Carrier, Cruiser, Destroyer, Dreadnought, Fighter, Flagship, WarSun,
    Infantry, Mech, PDS, SpaceDock,
    // 0.52.0 (owner D117): a second flagship of its own type - the Ghemina's Lady (their Flagship is the Lord). Last, so
    // the numbers saved games use stay the same; a ship like the ones before Infantry (isShip, kShipTypes).
    Flagship2,
    Count
};
constexpr int kUnitTypes = int(UnitType::Count);
// Every ship type: the old order (Carrier .. WarSun), then the second flagship.
constexpr UnitType kShipTypes[8] = {UnitType::Carrier, UnitType::Cruiser,  UnitType::Destroyer, UnitType::Dreadnought,
                                    UnitType::Fighter, UnitType::Flagship, UnitType::WarSun,    UnitType::Flagship2};
constexpr int kShipIdx[8] = {0, 1, 2, 3, 4, 5, 6, 11};  // the same as numbers
constexpr int kShipMaskAll = 0x7F | (1 << 11);           // the ship types as bits (1 << type)

// Wormhole bits
constexpr uint8_t kAlpha = 1, kBeta = 2, kGamma = 4, kDelta = 8;
constexpr uint8_t kEpsilon = 16;  // Thunder's Edge: the Crimson Rebellion's wormholes
// Anomaly bits
constexpr uint8_t kAsteroid = 1, kNebula = 2, kSupernova = 4, kRift = 8;
constexpr uint8_t kScar = 16;  // Thunder's Edge: entropic scar (no unit abilities in or against it)

struct PlanetDef {
    const char* key;
    const char* name;
    int8_t res, inf;
    Trait trait;
    TechColor skip;
    bool legendary;
    bool home;      // a faction home planet
    int16_t system; // index into kSystems
    // Thunder's Edge (0.34.0): planets with two traits / two technology specialties, space stations and
    // planets with a relic icon
    Trait trait2;
    TechColor skip2;
    uint8_t flags;  // kPlanetStation | kPlanetRelic
};
constexpr uint8_t kPlanetStation = 1, kPlanetRelic = 2;

struct SystemDef {
    const char* key;   // tile number as printed ("26", "83a")
    const char* name;
    Back back;
    uint8_t wormholes;
    uint8_t anomalies;
    Source source;
    int8_t planetCount;
    int16_t planets[3];
    uint8_t lanes[6];  // hyperlanes: lanes[i] = bitmask of edges joined to edge i (unrotated)
};

struct UnitDef {
    const char* key;
    const char* name;
    UnitType type;
    int8_t faction;     // -1 = generic
    int16_t tech;       // technology that unlocks this version, -1 = none
    int16_t upgradeOf;  // unit this one upgrades, -1 = none
    int8_t cost2;       // cost x2 (fighters and infantry cost 1 for two)
    int8_t move, capacity;
    int8_t combat, combatDice;
    int8_t afb, afbDice;
    int8_t bombard, bombardDice;
    int8_t cannon, cannonDice;
    bool deepCannon, sustain, shield, ignoresShield;
    int8_t production;
    bool productionPlusResources;  // space docks: planet resources + value
    bool spaceOnly;                // e.g. Saar floating factories
};

struct TechDef {
    const char* key;
    const char* name;
    TechColor color;    // None for faction "Valefar" techs
    bool unitUpgrade;
    uint8_t req[4];     // prerequisites per colour (blue, green, red, yellow)
    int8_t faction;     // -1 = generic
    int16_t replaces;   // faction unit upgrade: the generic upgrade it replaces
    Source source;
};

struct StartUnit {
    UnitType type;
    int8_t count;
    int8_t planet;  // index into the home planets, -1 = space
};

struct FactionDef {
    const char* key;
    const char* name;
    int16_t homeSystem;
    int8_t commodities;
    int8_t fleetCount;
    StartUnit fleet[10];
    int16_t startTechs[4];
    int16_t factionTechs[2];
    int16_t units[6];  // faction-specific unit definitions
    Source source;
};

// Names shown on the faction sheet (effects come with the faction stage).
struct FactionInfo {
    const char* abilities[3];
    const char* leaders[5];   // sorted: agents, commander, hero
    int8_t leaderType[5];     // 0 agent, 1 commander, 2 hero, -1 none
    const char* notes[2];     // promissory notes
};

// Leaders (Prophecy of Kings): agents, commanders and heroes.
enum LeaderType { kAgent = 0, kCommander = 1, kHero = 2 };
struct LeaderDef {
    const char* key;   // e.g. "solagent"
    const char* name;
    int8_t faction;
    int8_t type;       // LeaderType
};

struct ObjectiveDef {
    const char* key;
    const char* name;
    int8_t kind;    // 1 = stage I public, 2 = stage II public, 3 = secret
    int8_t points;
    ObjPhase phase;
    Source source;
};

struct ActionCardDef {
    const char* key;
    const char* name;
    int8_t count;  // copies in the deck
    Source source;
};

// What an agenda is voted on.
enum class Elect : uint8_t { ForAgainst, Player, Planet, NonHomePlanet, Law, ScoredSecret, StrategyCard, Covert };

struct AgendaDef {
    const char* key;
    const char* name;
    bool law;
    Elect elect;
    Source source;
};

// Exploration (Prophecy of Kings)
enum class ExploreType : uint8_t { Cultural, Hazardous, Industrial, Frontier };
// Chart: Uncharted Space's Star Charts - kept in front of the player like relic fragments (and traded like
// them), but they are not fragments.
enum class ExploreKind : uint8_t { Instant, Attach, Fragment, Token, Chart };
struct ExploreCardDef {
    const char* key;
    const char* name;
    ExploreType type;
    int8_t count;
    ExploreKind kind;
    Source source;  // PoK, or Uncharted (0.33.0: only with that module)
};
struct RelicDef {
    const char* key;
    const char* name;
    Source source;
};

struct LayoutCell {
    int16_t pos;   // ring*100 + index
    int8_t kind;   // 0 fixed tile, 1 home, 2 slice tile, 3 (0.58.0, standard layouts) an extra tile next to Mecatol Rex
    int16_t a;     // tile index / player / extra: 0 blue, 1 red, 2 either
    int8_t b;      // rotation / slice slot / home: trade goods at the start (standard layouts)
};
struct LayoutDef {
    int8_t players;
    int16_t first, count;
};
// 0.58.0 (owner: a standard map without hyperlanes at any player count): the printed galaxies of the Living Rules
// Reference's board setups (tools/gen_std_layouts.py) - blue and red tiles per player (LRR setup step 6)
struct StdLayoutDef {
    int8_t players, blue, red;
    int16_t first, count;
};

extern const PlanetDef kPlanets[];
extern const SystemDef kSystems[];
extern UnitDef kUnits[];  // (0.43.3: not const - the Codex Omega names are switched in, setCodexTexts)
extern TechDef kTechs[];
extern const FactionDef kFactions[];
extern const FactionInfo kFactionInfo[];
// Discordant Stars (0.37.0): factions that choose their starting technologies
struct StartChoiceDef {
    int16_t faction;
    int8_t count;
    int16_t techs[8];  // the choices (-1 = none listed: the faction's own rule - Edyn, Kjalengard)
};
extern const StartChoiceDef kStartChoices[];
extern const int kStartChoiceCount;
extern ObjectiveDef kObjectives[];
extern const ActionCardDef kActionCards[];
extern const AgendaDef kAgendas[];
extern const ExploreCardDef kExploreCards[];
extern const RelicDef kRelics[];
extern LeaderDef kLeaders[];
extern const LayoutCell kLayoutCells[];
extern const LayoutDef kLayouts[];
extern const LayoutCell kStdLayoutCells[];
extern const StdLayoutDef kStdLayouts[];
extern const int kStdLayoutCount;
extern const int kPlanetCount, kSystemCount, kUnitCount, kTechCount, kFactionCount, kObjectiveCount, kLayoutCount;
extern const int kActionCardCount, kAgendaCount, kExploreCardCount, kRelicCount, kLeaderCount;

// Lookups (return -1 if not found)
int findSystem(const char* key);
int findTech(const char* key);
int findUnit(const char* key);
int findFaction(const char* key);
int findObjective(const char* key);
int findActionCard(const char* key);
int findAgenda(const char* key);
int findExploreCard(const char* key);
int findRelic(const char* key);
int findPlanet(const char* key);
int findLeader(const char* key);
int genericUnit(UnitType t);  // index of the basic (unupgraded) generic unit

const char* unitTypeName(UnitType t, bool plural = false);
int unitByKey(const char* key);  // kUnits index, -1 = none (0.52.0)
const char* unitTypeShort(UnitType t);  // two-letter code for compact displays
const char* traitName(Trait t);
const char* colorName(TechColor c);
const char* factionShortName(int faction);

// Short descriptions in our own words.
const char* techSummary(int tech);
const char* objectiveSummary(int objective);
bool objectiveImplemented(int objective);  // usable with the rules built so far
bool techImplemented(int tech);

// Card texts in our own words (card_text.cpp).
const char* actionCardWhen(int card);
const char* actionCardText(int card);
bool actionCardImplemented(int card);
bool actionCardIsComponent(int card);  // played as a component action ("Action:")
const char* agendaText(int agenda, bool against);  // For / elect effect, or Against effect
bool agendaImplemented(int agenda);
const char* exploreText(int card);
const char* relicText(int relic);
const char* legendaryName(int planetDef);   // legendary planet ability card name ("" if none)
const char* legendaryText(int planetDef);
const char* exploreTypeName(ExploreType t);

// Faction abilities, leaders, faction notes, special units (faction_text.cpp).
bool factionImplemented(int faction);         // its abilities work (Stage 5 batches)
int dsBatch(int faction);                     // Discordant Stars: the batch (version) it arrived in, 0 = not yet
bool factionInPool(int faction, int dsLevel); // may be dealt / drawn at random in a game with that Setup::dsLevel
const char* abilityText(int faction, int i);  // i-th ability in kFactionInfo
const char* leaderText(int leader);
const char* leaderUnlock(int leader);         // what unlocks a commander / hero
const char* unitAbilityText(int unit);        // flagship / mech / special unit ability ("" if none)
// 0.31.0: show the Codex Omega wording (a Codex game is open); 0.43.3: their names get an Omega sign, and latest =
// the game uses Thunder's Edge's Codex (Setup::fixes >= 4: X-89 Bacterial Weapon's newest version)
void setCodexTexts(bool on, bool latest = true);
// (0.57.1) Thunder's Edge's own Xxekir Grom (teXxchaHero): its name without the Omega sign and its own text. Call after
// setCodexTexts.
void setThundersEdgeTexts(bool xxchaHero, bool naalu = false);
bool teXxchaHeroTexts();
bool teNaaluTexts();  // (fixes 27) Thunder's Edge's Z'eu and Iconoclast
void setWormholeGeneratorOriginal(bool on);  // 0.44.9: the original card's wording (games without the Codex)
void setMagmusReactorOriginal(bool on);      // (fixes 26) the original Magmus Reactor's wording (no Codex / Thunder's Edge)
std::string plainName(const char* name);  // a card's name without the Omega sign
bool codexTexts();
const char* factionNoteName(int faction, int type);  // kNoteAlliance / kNoteFaction / kNoteFaction2
// Thunder's Edge galactic events (0.36.0): Setup::events / Game::events bits, ticked on the Modules screen
enum GalacticEvent {
    kEvCommerce, kEvVoid, kEvWilds, kEvHidden, kEvExploration, kEvCivilized, kEvMinor, kEvAtomics, kEvFighters, kEvTotalWar,
    kEvWild, kEvWormholes, kEvMonuments, kEvCosmic, kEvCultural, kEvMercenaries, kEvMobilization, kEvOrthodoxy, kEvWarSun,
    kEvConventions, kEventCount
};
// Thunder's Edge galactic events (0.36.0): name, our own short wording, playable yet
struct GalacticEventDef {
    const char* key;
    const char* name;
    const char* text;
    bool done;
};
const GalacticEventDef& galacticEvent(int ev);
const char* factionNoteText(int faction, int type);

// Generic promissory notes every player owns (faction notes come with the
// faction abilities).
constexpr int kNoteTypes = 4;
enum NoteType { kNoteCeasefire = 0, kNoteTradeAgreement = 1, kNotePoliticalSecret = 2, kNoteSupportThrone = 3 };
const char* noteName(int type);
const char* noteText(int type);

constexpr int kStrategyCards = 8;
const char* strategyName(int card);  // card 0..7 = initiative 1..8
void setStrategyTexts(bool thundersEdge);  // 0.43.3: Thunder's Edge's Construction / Warfare wording
const char* strategyPrimary(int card);
const char* strategySecondary(int card);

inline bool isShip(UnitType t) { return t <= UnitType::WarSun || t == UnitType::Flagship2; }
inline bool isFlagship(UnitType t) { return t == UnitType::Flagship || t == UnitType::Flagship2; }  // (0.52.0)
inline bool isGroundForce(UnitType t) { return t == UnitType::Infantry || t == UnitType::Mech; }
inline bool isStructure(UnitType t) { return t == UnitType::PDS || t == UnitType::SpaceDock; }
inline bool isTransported(UnitType t) { return t == UnitType::Fighter || isGroundForce(t); }

}  // namespace ti
